//! 🌱️ Original Drawing birth custody funds only parent reference duplication before exact payload transfer.
use semio_s_artifact_layout_layout_model::{LayoutDrawingBirth,LayoutDrawingMember};
use semio_framework_os_kernel::RetainedFieldPreparation;
use semio_framework_value::{RetireOwned,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneSourceTake,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use std::mem::{size_of,ManuallyDrop};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Drawing import birth lost original custody")}
/// 🧳️ The only new semantic owner is one reference record; the original typed payload remains under its admitted authority.
pub struct DrawingBirthPreparation<S:RetireOwned+Sync+'static>{source:ManuallyDrop<Option<RetainedCloneSource<LayoutDrawingMember,LayoutDrawingBirth<S>>>>,field:RetainedFieldPreparation<LayoutDrawingMember>,parent:ManuallyDrop<Option<LayoutDrawingMember>>,birth:ManuallyDrop<Option<LayoutDrawingBirth<S>>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
impl<S:RetireOwned+Sync+'static> DrawingBirthPreparation<S>{
 const FIXED:usize=size_of::<Self>()*2+256;
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:Self::FIXED,depth:1,..Default::default()}}
 fn nested(d:RetirementDemand)->RetirementDemand{RetirementDemand{copy_bytes:d.copy_bytes+Self::FIXED,depth:d.depth+1,..d}}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-Self::FIXED,maximum_depth:g.maximum_depth-1,..g}}
 fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=Self::FIXED;p}
 fn paid(e:ValueError)->ValueError{let p=Self::receipt(e.retained_progress());e.with_retained_progress(p)}
 /// 📏️ Quotes the shared original authority and its lease before accepting the authored birth.
 pub fn admission_demand()->RetirementDemand{let d=RetainedCloneSource::<LayoutDrawingMember,LayoutDrawingBirth<S>>::borrowed_constructor_demand::<LayoutDrawingBirth<S>>();RetirementDemand{capacity_bytes:d.capacity_bytes,..Self::nested(RetirementDemand{copy_bytes:RetainedCloneSource::<LayoutDrawingMember,LayoutDrawingBirth<S>>::borrowed_constructor_copy_bytes::<LayoutDrawingBirth<S>>(),depth:d.depth,..Default::default()})}}
 /// 🎟️ Admits the same original birth owner and lends only its member projection.
 pub fn admit(birth:LayoutDrawingBirth<S>,g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),(ValueError,LayoutDrawingBirth<S>)>{let d=Self::admission_demand();if !retained_clone_grant_admits(g,d){return Err((fault(),birth))}let(source,p)=match RetainedCloneSource::<LayoutDrawingMember,LayoutDrawingBirth<S>>::admit_borrowed(birth,|b|&b.member,Self::child(g)){Ok(value)=>value,Err((e,birth))=>return Err((Self::paid(e),birth))};Ok((Self{source:ManuallyDrop::new(Some(source)),field:Default::default(),parent:ManuallyDrop::new(None),birth:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false},Self::receipt(p)))}
 pub fn ready(&self)->bool{self.phase==4&&!self.closing}
 pub fn demand(&self,_body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(fault())}Ok(match self.phase{0=>if self.field.value().is_some(){Self::fixed()}else{Self::nested(self.field.demand(self.source.as_ref().ok_or_else(fault)?.borrow(),256)?)},1=>Self::nested(self.field.exchange_demand()?),2=>if self.field.terminal_is_empty(){Self::fixed()}else{Self::nested(self.field.close_demand(256)?)},3=>Self::nested(self.source.as_ref().ok_or_else(fault)?.next_take_demand(256)?),4=>Self::fixed(),_=>return Err(fault())})}
 pub fn advance(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{0=>if self.field.value().is_some(){self.phase=1}else{p=Self::receipt(self.field.advance(self.source.as_ref().ok_or_else(fault)?.borrow(),256,Self::child(g)).map_err(Self::paid)?.progress())},1=>{let(value,paid)=self.field.take(Self::child(g)).map_err(Self::paid)?;p=Self::receipt(paid);*self.parent=value;self.field.begin_close();self.phase=2},2=>if self.field.terminal_is_empty(){self.phase=3}else{p=Self::receipt(self.field.close_step(Self::child(g)).map_err(Self::paid)?.progress())},3=>match self.source.as_mut().ok_or_else(fault)?.take_authority(Self::child(g)).map_err(Self::paid)?{RetainedCloneSourceTake::Pending(progress)=>p=Self::receipt(progress),RetainedCloneSourceTake::Ready(birth,progress)=>{p=Self::receipt(progress);*self.birth=Some(birth);*self.source=None;self.phase=4}},4=>return Ok(RetainedCloneStep::Complete(p)),_=>return Err(fault())}Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(fault())}Ok(Self::fixed())}
 /// 📤️ Transfers the prepared parent reference and the exact original birth without reconstructing either payload.
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<(LayoutDrawingMember,LayoutDrawingBirth<S>)>,RetainedCloneProgress),ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}let parent=self.parent.take().ok_or_else(fault)?;let birth=self.birth.take().ok_or_else(fault)?;self.phase=5;Ok((Some((parent,birth)),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true;self.field.begin_close()}
 pub fn close_demand(&self,_body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(fault())}if !self.field.terminal_is_empty(){return Ok(Self::nested(self.field.close_demand(256)?))}if let Some(source)=self.source.as_ref(){return Ok(Self::nested(source.next_close_demand(256)?))}if !self.retirement.is_empty()||self.parent.is_some(){return Ok(Self::nested(self.retirement.next_owner_demands::<LayoutDrawingMember>(self.parent.is_some(),&None,256)?))}if self.birth.is_some(){return Ok(Self::nested(self.retirement.next_owner_demands::<LayoutDrawingBirth<S>>(true,&None,256)?))}Ok(Self::fixed())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.field.terminal_is_empty(){return self.field.close_step(Self::child(g)).map(|s|RetainedCloneStep::Progress(Self::receipt(s.progress()))).map_err(Self::paid)}if let Some(source)=self.source.as_mut(){let step=source.close_step(Self::child(g)).map_err(Self::paid)?;let p=Self::receipt(step.progress());if source.terminal_is_empty(){*self.source=None}return Ok(RetainedCloneStep::Progress(p))}if !self.retirement.is_empty(){return self.retirement.step_granted(Self::child(g)).map(|s|RetainedCloneStep::Progress(Self::receipt(s.progress()))).map_err(Self::paid)}if let Some(step)=self.retirement.begin_granted(&mut self.parent,Self::child(g)).map_err(Self::paid)?{return Ok(RetainedCloneStep::Progress(Self::receipt(step.progress())))}if let Some(step)=self.retirement.begin_granted(&mut self.birth,Self::child(g)).map_err(Self::paid)?{return Ok(RetainedCloneStep::Progress(Self::receipt(step.progress())))}Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.field.terminal_is_empty()&&self.source.is_none()&&self.parent.is_none()&&self.birth.is_none()&&self.retirement.is_empty()}
}
impl<S:RetireOwned+Sync+'static> Drop for DrawingBirthPreparation<S>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"Drawing birth preparation requires original-funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.source);ManuallyDrop::drop(&mut self.parent);ManuallyDrop::drop(&mut self.birth)}}}}

